def _random(rng: np.random.Generator | None) -> Any:
    """The source of random draws: the given Generator, or NumPy's global RNG (default)."""
    return np.random if rng is None else rng


class _SeededSampling:
    """The fork's rng-aware predict and sampling methods (mixed into a Prophet subclass)."""

    # Attributes provided by the Prophet class this is mixed into.
    history: Any
    params: Any
    uncertainty_samples: int
    interval_width: float
    mcmc_samples: int
    y_scale: Any
    extra_regressors: Any
    changepoints_t: Any
    growth: str
    logistic_floor: bool
    setup_dataframe: Any
    predict_trend: Any
    predict_seasonal_components: Any
    make_all_seasonality_features: Any
    piecewise_linear: Any
    piecewise_logistic: Any
    flat_trend: Any
    percentile: Any
    _make_historical_mat_time: Any

    def predict(
        self,
        df: pd.DataFrame | None = None,
        vectorized: bool = True,
        history_uncertainty: bool | Literal['analytic', 'sampled'] = True,
        rng: np.random.Generator | None = None,
    ) -> pd.DataFrame:
        """Predict using the prophet model.

        Parameters
        ----------
        df: pd.DataFrame with dates for predictions (column ds), and capacity
            (column cap) if logistic growth. If not provided, predictions are
            made on the history.
        vectorized: Whether to use a vectorized method to compute uncertainty intervals. Suggest using
            True (the default) for much faster runtimes in most cases,
            except when (growth = 'logistic' and mcmc_samples > 0).
        history_uncertainty: Whether to compute yhat/trend uncertainty intervals for rows
            within the history (ds up to the last training date). True (the default)
            computes them for every row: with rng given and a MAP fit, history rows
            draw only the order statistics the percentiles read (the same
            distribution as sampling every path, far faster), otherwise every
            path is sampled. 'sampled' always samples every path. False leaves them NaN for history rows and only
            samples the future rows, which is much faster when the history is included;
            the future intervals are then exactly those of predicting the future rows alone.
            'analytic' (MAP fits only) samples the future rows as False does and gives
            history rows the exact limit of the sampled intervals: yhat +/- z * sigma_obs *
            y_scale, with z the normal quantile for interval_width, and trend bounds equal
            to the trend.
        rng: Optional numpy Generator for all random draws (uncertainty intervals,
            regressor models). None (the default) uses NumPy's global RNG, as before.

        Returns
        -------
        A pd.DataFrame with the forecast components.
        """
        if self.history is None:
            raise Exception('Model has not been fit.')
        analytic = (isinstance(history_uncertainty, str)
                    and history_uncertainty == 'analytic')
        sampled = (isinstance(history_uncertainty, str)
                   and history_uncertainty == 'sampled')
        if not (analytic or sampled
                or isinstance(history_uncertainty, (bool, np.bool_))):
            raise ValueError(
                "history_uncertainty must be True, False, 'analytic' or "
                "'sampled', got {!r}.".format(history_uncertainty))
        if analytic and self.mcmc_samples > 0:
            raise ValueError(
                "history_uncertainty='analytic' requires a MAP fit (mcmc_samples=0).")

        regressor_samples = None
        if df is None:
            df = self.history.copy()
        else:
            if df.shape[0] == 0:
                raise ValueError('Dataframe has no rows.')
            df, regressor_samples = self._prepare_regressors_for_predict(
                df.copy(),
                self.uncertainty_samples if self.uncertainty_samples else None,
                rng=rng,
            )
            df = self.setup_dataframe(df)

        if regressor_samples:
            standardized_samples = {}
            for name, samples in regressor_samples.items():
                props = self.extra_regressors[name]
                standardized_samples[name] = (samples - props['mu']) / props['std']
            regressor_samples = standardized_samples

        df['trend'] = self.predict_trend(df)
        seasonal_components = self.predict_seasonal_components(df)
        # MAP history rows differ between samples only by iid noise, so their
        # percentiles can come from the order statistics alone.
        order_stats = (rng is not None
                       and isinstance(history_uncertainty, (bool, np.bool_))
                       and bool(history_uncertainty) and vectorized
                       and self.mcmc_samples == 0 and not regressor_samples)
        if self.uncertainty_samples:
            if history_uncertainty and not analytic and not order_stats:
                intervals = self.predict_uncertainty(df, vectorized, regressor_samples, rng=rng)
            else:
                intervals = self._future_uncertainty(df, vectorized, regressor_samples, rng=rng)
        else:
            intervals = None

        # Drop columns except ds, cap, floor, and trend
        cols = ['ds', 'trend']
        if 'cap' in df:
            cols.append('cap')
        if self.logistic_floor:
            cols.append('floor')
        # Add in forecast components
        df2 = pd.concat((df[cols], intervals, seasonal_components), axis=1)
        df2['yhat'] = (
                df2['trend'] * (1 + df2['multiplicative_terms'])
                + df2['additive_terms']
        )
        if analytic and intervals is not None:
            self._analytic_history_intervals(df2, (df['t'] <= 1).to_numpy())
        elif order_stats and intervals is not None:
            self._order_statistic_history_intervals(
                df2, (df['t'] <= 1).to_numpy(), cast(np.random.Generator, rng))
        return df2

    def _prepare_regressors_for_predict(
        self, df: pd.DataFrame, n_samples: int | None = None,
        rng: np.random.Generator | None = None,
    ) -> tuple[pd.DataFrame, dict[str, npt.NDArray[np.float64]] | None]:
        """Populate regressor columns using fitted regressor models if present.

        Returns updated dataframe and optional regressor sample draws.
        """
        regressor_samples: dict[str, npt.NDArray[np.float64]] | None = (
            {} if n_samples else None
        )
        last_history_date = self.history['ds'].max() if self.history is not None else None
        for name, props in self.extra_regressors.items():
            predictor = props.get('predictor')
            if props.get('predictor_spec') is None or predictor is None:
                continue
            if name not in df:
                df[name] = np.nan
            future_mask = (
                df['ds'] > last_history_date
                if last_history_date is not None
                else df[name].isna()
            )
            history_mask = ~future_mask
            if history_mask.any():
                missing_hist = history_mask & df[name].isna()
                if missing_hist.any() and self.history is not None and name in self.history:
                    hist_lookup = self.history.set_index('ds')[name]
                    props = self.extra_regressors[name]
                    hist_lookup = hist_lookup * props['std'] + props['mu']
                    df.loc[missing_hist, name] = hist_lookup.reindex(
                        df.loc[missing_hist, 'ds']
                    ).to_numpy()
            if future_mask.any():
                future_dates = df.loc[future_mask, 'ds']
                reg_future = pd.DataFrame({'ds': future_dates})
                logger.info(
                    "Running regressor model '%s' for %d future dates",
                    name,
                    len(reg_future),
                )
                # Pass rng only when given, so the default call is unchanged.
                rng_kw = {} if rng is None else {'rng': rng}
                reg_pred = seeded(predictor).predict(reg_future, **rng_kw)
                df.loc[future_mask, name] = reg_pred['yhat'].to_numpy()
                if n_samples and regressor_samples is not None:
                    sample_dict = seeded(predictor).predictive_samples(reg_future, **rng_kw)
                    reg_samples = sample_dict['yhat']
                    samples_full = np.tile(
                        df[name].to_numpy()[:, None], (1, reg_samples.shape[1])
                    )
                    # Use boolean indexing on ndarray, not pandas ExtensionArray 2D slice.
                    samples_full[future_mask.to_numpy(), :] = reg_samples
                    regressor_samples[name] = samples_full
                    logger.info(
                        "Collected %d predictive samples for regressor '%s'",
                        reg_samples.shape[1],
                        name,
                    )
            elif n_samples and regressor_samples is not None:
                n_draws = n_samples if isinstance(n_samples, int) else 1
                regressor_samples[name] = np.tile(
                    df[name].to_numpy()[:, None], (1, n_draws)
                )
        if regressor_samples is not None and len(regressor_samples) == 0:
            regressor_samples = None
        return df, regressor_samples

    def predict_uncertainty(
        self,
        df: pd.DataFrame,
        vectorized: bool,
        regressor_samples: dict[str, npt.NDArray[np.float64]] | None = None,
        rng: np.random.Generator | None = None,
    ) -> pd.DataFrame:
        """Prediction intervals for yhat and trend.

        Parameters
        ----------
        df: Prediction dataframe.
        vectorized: Whether to use a vectorized method for generating future draws.
        regressor_samples: Optional draws for regressor values (already standardized)
            aligned with df.

        Returns
        -------
        Dataframe with uncertainty intervals.
        """
        sim_values = self.sample_posterior_predictive(df, vectorized, regressor_samples, rng=rng)

        lower_p = 100 * (1.0 - self.interval_width) / 2
        upper_p = 100 * (1.0 + self.interval_width) / 2

        series = {}
        for key in ['yhat', 'trend']:
            # Both bounds in one call: a single partition pass over the samples.
            if key == 'trend':
                # Historical trend has no sampled uncertainty under MAP.
                lower, upper = self._percentile_skip_constant_rows(
                    sim_values[key], [lower_p, upper_p])
            else:
                lower, upper = self.percentile(
                    sim_values[key], [lower_p, upper_p], axis=1)
            series['{}_lower'.format(key)] = lower
            series['{}_upper'.format(key)] = upper

        return pd.DataFrame(series)

    def _future_uncertainty(
        self,
        df: pd.DataFrame,
        vectorized: bool,
        regressor_samples: dict[str, npt.NDArray[np.float64]] | None = None,
        rng: np.random.Generator | None = None,
    ) -> pd.DataFrame:
        """predict_uncertainty for future rows (t > 1) only; NaN for history rows."""
        future = (df['t'] > 1).to_numpy()
        columns = ['yhat_lower', 'yhat_upper', 'trend_lower', 'trend_upper']
        intervals = pd.DataFrame(np.nan, index=df.index, columns=columns)
        if future.any():
            future_samples = None
            if regressor_samples:
                future_samples = {k: v[future] for k, v in regressor_samples.items()}
            future_intervals = self.predict_uncertainty(
                df.loc[future].reset_index(drop=True), vectorized, future_samples, rng=rng)
            intervals.loc[future, columns] = future_intervals[columns].to_numpy()
        return intervals

    def _analytic_history_intervals(
        self, fcst: pd.DataFrame, history: np.ndarray
    ) -> None:
        """Fill yhat/trend intervals of history rows in closed form (MAP fits).

        With one parameter set, history samples differ only by the Gaussian
        noise (the sampled trend is deterministic for t <= 1), so the sampled
        percentiles converge to yhat +/- z * sigma_obs * y_scale.

        Parameters
        ----------
        fcst: Forecast dataframe with yhat and trend; updated in place.
        history: Boolean mask of the history rows (t <= 1).
        """
        if not history.any():
            return
        z = NormalDist().inv_cdf((1 + self.interval_width) / 2)
        sigma = float(np.ravel(self.params['sigma_obs'])[0])
        half_width = z * sigma * cast(float, self.y_scale)
        yhat = fcst.loc[history, 'yhat'].to_numpy()
        trend = fcst.loc[history, 'trend'].to_numpy()
        fcst.loc[history, 'yhat_lower'] = yhat - half_width
        fcst.loc[history, 'yhat_upper'] = yhat + half_width
        fcst.loc[history, 'trend_lower'] = trend
        fcst.loc[history, 'trend_upper'] = trend

    def _order_statistic_history_intervals(
        self, fcst: pd.DataFrame, history: np.ndarray,
        rng: np.random.Generator,
    ) -> None:
        """Fill yhat/trend intervals of history rows from order statistics.

        With one parameter set (MAP), the uncertainty_samples draws of a
        history row are yhat + iid N(0, sigma_obs) * y_scale (the sampled
        trend is deterministic for t <= 1). The interval bounds are linear
        percentiles of those draws, which read two order statistics each;
        those are drawn directly, so the bounds have the distribution of
        sampling every path at a cost per row instead of per draw. Trend
        bounds equal the trend, as sampling gives.

        Parameters
        ----------
        fcst: Forecast dataframe with yhat and trend; updated in place.
        history: Boolean mask of the history rows (t <= 1).
        rng: numpy Generator for the draws.
        """
        if not history.any():
            return
        n = int(self.uncertainty_samples)
        percents = [100 * (1.0 - self.interval_width) / 2,
                    100 * (1.0 + self.interval_width) / 2]
        # numpy's linear percentile: position j + g = (n - 1) * q
        spots = []
        for q in percents:
            pos = (n - 1) * (q / 100)
            j = min(max(int(np.floor(pos)), 0), n - 1)
            spots.append((j, float(pos - np.floor(pos))))
        ranks = sorted({r for j, _ in spots for r in (j + 1, min(j + 2, n))})
        # Uniform order statistics are a Markov chain: given U(r') = u,
        # U(r) = u + (1 - u) * Beta(r - r', n - r + 1).
        rows = int(history.sum())
        u = np.zeros(rows)
        prev = 0
        z = {}
        for r in ranks:
            u = u + (1 - u) * rng.beta(r - prev, n - r + 1, rows)
            prev = r
            z[r] = self._norm_ppf(np.clip(u, np.finfo(float).tiny,
                                          np.nextafter(1.0, 0.0)))
        sigma = float(np.ravel(self.params['sigma_obs'])[0])
        scale = sigma * cast(float, self.y_scale)
        yhat = fcst.loc[history, 'yhat'].to_numpy()
        trend = fcst.loc[history, 'trend'].to_numpy()
        for (j, g), col in zip(spots, ['yhat_lower', 'yhat_upper']):
            a, b = z[j + 1], z[min(j + 2, n)]
            # the interpolation of np.percentile's linear method
            q_z = b - (b - a) * (1 - g) if g >= 0.5 else a + (b - a) * g
            fcst.loc[history, col] = yhat + scale * q_z
        fcst.loc[history, 'trend_lower'] = trend
        fcst.loc[history, 'trend_upper'] = trend

    @staticmethod
    def _norm_ppf(p: np.ndarray) -> np.ndarray:
        """Inverse standard normal CDF for p in (0, 1), vectorized.

        Wichura's algorithm AS 241 (PPND16), accurate to about 1e-16.

        Parameters
        ----------
        p: Probabilities in (0, 1).

        Returns
        -------
        The standard normal quantiles of p.
        """
        a = (3.387132872796366608, 133.14166789178437745,
             1971.5909503065514427, 13731.693765509461125,
             45921.953931549871457, 67265.770927008700853,
             33430.575583588128105, 2509.0809287301226727)
        b = (1.0, 42.313330701600911252, 687.1870074920579083,
             5394.1960214247511077, 21213.794301586595867,
             39307.89580009271061, 28729.085735721942674,
             5226.495278852545925)
        c = (1.42343711074968357734, 4.6303378461565452959,
             5.7694972214606914055, 3.64784832476320460504,
             1.27045825245236838258, 0.24178072517745061177,
             0.0227238449892691845833, 7.7454501427834140764e-4)
        d = (1.0, 2.05319162663775882187, 1.6763848301838038494,
             0.68976733498510000455, 0.14810397642748007459,
             0.0151986665636164571966, 5.475938084995344946e-4,
             1.05075007164441684324e-9)
        e = (6.6579046435011037772, 5.4637849111641143699,
             1.7848265399172913358, 0.29656057182850489123,
             0.026532189526576123093, 0.0012426609473880784386,
             2.71155556874348757815e-5, 2.01033439929228813265e-7)
        f = (1.0, 0.59983220655588793769, 0.13692988092273580531,
             0.0148753612908506148525, 7.868691311456132591e-4,
             1.8463183175100546818e-5, 1.4215117583164458887e-7,
             2.04426310338993978564e-15)

        def poly(coef: tuple[float, ...], x: np.ndarray) -> np.ndarray:
            out = np.full_like(x, coef[-1])
            for k in reversed(coef[:-1]):
                out = out * x + k
            return out

        p = np.asarray(p, dtype=float)
        q = p - 0.5
        out = np.empty_like(p)
        central = np.abs(q) <= 0.425
        r = 0.180625 - q[central] ** 2
        out[central] = q[central] * poly(a, r) / poly(b, r)
        tail = ~central
        r = np.sqrt(-np.log(np.minimum(p[tail], 1 - p[tail])))
        near = r <= 5.0
        val = np.empty_like(r)
        val[near] = poly(c, r[near] - 1.6) / poly(d, r[near] - 1.6)
        val[~near] = poly(e, r[~near] - 5.0) / poly(f, r[~near] - 5.0)
        out[tail] = np.where(q[tail] < 0, -val, val)
        return out

    def sample_posterior_predictive(
        self,
        df: pd.DataFrame,
        vectorized: bool,
        regressor_samples: dict[str, np.ndarray] | None = None,
        rng: np.random.Generator | None = None,
    ) -> dict[str, npt.NDArray[np.float64]]:
        """Prophet posterior predictive samples.

        Parameters
        ----------
        df: Prediction dataframe.
        vectorized: Whether to use a vectorized method to generate future draws.
        regressor_samples: Optional draws for regressors (standardized) keyed by
            regressor name. If provided, regressor uncertainty will be propagated
            through forecast draws.

        Returns
        -------
        Dictionary with posterior predictive samples for the forecast yhat and
        for the trend component.
        """
        n_iterations = self.params['k'].shape[0]
        samp_per_iter = max(1, int(np.ceil(
            self.uncertainty_samples / float(n_iterations)
        )))
        # Generate seasonality features once so we can re-use them.
        seasonal_features, _, component_cols, _ = (
            self.make_all_seasonality_features(df)
        )
        sim_values = {'yhat': [], 'trend': []}
        regressor_positions: dict[str, int] = {}
        regressor_draw_counts: dict[str, int] = {}
        if regressor_samples:
            vectorized = False
            for name in regressor_samples:
                if name not in seasonal_features.columns:
                    continue
                pos = seasonal_features.columns.get_loc(name)
                if not isinstance(pos, (int, np.integer)):
                    raise ValueError(
                        f"Expected a unique column position for regressor '{name}'"
                    )
                regressor_positions[name] = int(pos)
                regressor_draw_counts[name] = regressor_samples[name].shape[1]
        sample_counter = 0
        for i in range(n_iterations):
            if vectorized:
                sims = self.sample_model_vectorized(
                    df=df,
                    seasonal_features=seasonal_features,
                    iteration=i,
                    s_a=component_cols['additive_terms'],
                    s_m=component_cols['multiplicative_terms'],
                    n_samples=samp_per_iter,
                    rng=rng,
                )
            else:
                sims = []
                for _ in range(samp_per_iter):
                    seasonal_features_sample = seasonal_features
                    if regressor_samples:
                        seasonal_features_sample = seasonal_features.copy()
                        for name, pos in regressor_positions.items():
                            draw_count = regressor_draw_counts[name]
                            use_idx = sample_counter % draw_count
                            seasonal_features_sample.iloc[:, int(pos)] = (
                                regressor_samples[name][:, use_idx]
                            )
                    sims.append(
                        self.sample_model(
                            df=df,
                            seasonal_features=seasonal_features_sample,
                            iteration=i,
                            s_a=component_cols['additive_terms'],
                            s_m=component_cols['multiplicative_terms'],
                            rng=rng,
                        )
                    )
                    sample_counter += 1
            for key in sim_values:
                for sim in sims:
                    sim_values[key].append(sim[key])

        return {k: np.column_stack(v) for k, v in sim_values.items()}

    def sample_model(
        self,
        df: pd.DataFrame,
        seasonal_features: pd.DataFrame,
        iteration: int,
        s_a: pd.Series,
        s_m: pd.Series,
        rng: np.random.Generator | None = None,
    ) -> dict[str, npt.NDArray[np.float64]]:
        """Simulate observations from the extrapolated generative model.

        Parameters
        ----------
        df: Prediction dataframe.
        seasonal_features: pd.DataFrame of seasonal features.
        iteration: Int sampling iteration to use parameters from.
        s_a: Indicator vector for additive components
        s_m: Indicator vector for multiplicative components

        Returns
        -------
        Dictionary with `yhat` and `trend`, each like df['t'].
        """
        trend = self.sample_predictive_trend(df, iteration, rng=rng)

        y_scale = cast(float, self.y_scale)
        beta = self.params['beta'][iteration]
        Xb_a = np.matmul(seasonal_features.values,
                         beta * s_a.values) * y_scale
        Xb_m = np.matmul(seasonal_features.values, beta * s_m.values)

        sigma = self.params['sigma_obs'][iteration]
        noise = _random(rng).normal(0, sigma, df.shape[0]) * y_scale

        return {
            'yhat': trend * (1 + Xb_m) + Xb_a + noise,
            'trend': trend
        }

    def sample_model_vectorized(
        self,
        df: pd.DataFrame,
        seasonal_features: pd.DataFrame,
        iteration: int,
        s_a: pd.Series,
        s_m: pd.Series,
        n_samples: int,
        rng: np.random.Generator | None = None,
    ) -> list[dict[str, np.ndarray]]:
        """Simulate observations from the extrapolated generative model. Vectorized version of sample_model().

        Parameters
        ----------
        df: Prediction dataframe.
        seasonal_features: pd.DataFrame of seasonal features.
        iteration: Int sampling iteration to use parameters from.
        s_a: Indicator vector for additive components.
        s_m: Indicator vector for multiplicative components.
        n_samples: Number of future paths of the trend to simulate.

        Returns
        -------
        List (length n_samples) of dictionaries with arrays for trend and yhat, each ordered like df['t'].
        """
        # Get the seasonality and regressor components, which are deterministic per iteration
        beta = self.params['beta'][iteration]
        Xb_a = np.matmul(seasonal_features.values,
                        beta * s_a.values) * self.y_scale
        Xb_m = np.matmul(seasonal_features.values, beta * s_m.values)
        # Get the future trend, which is stochastic per iteration
        trends = self.sample_predictive_trend_vectorized(
            df, n_samples, iteration, rng=rng)  # already on the same scale as the actual data
        sigma = self.params['sigma_obs'][iteration]
        noise_terms = _random(rng).normal(0, sigma, trends.shape) * cast(float, self.y_scale)

        simulations = []
        for trend, noise in zip(trends, noise_terms):
            simulations.append({
                'yhat': trend * (1 + Xb_m) + Xb_a + noise,
                'trend': trend
            })
        return simulations

    def sample_predictive_trend(
        self, df: pd.DataFrame, iteration: int, rng: np.random.Generator | None = None
    ) -> np.ndarray:
        """Simulate the trend using the extrapolated generative model.

        Parameters
        ----------
        df: Prediction dataframe.
        iteration: Int sampling iteration to use parameters from.

        Returns
        -------
        np.array of simulated trend over df['t'].
        """
        k = self.params['k'][iteration]
        m = self.params['m'][iteration]
        deltas = self.params['delta'][iteration]

        t = np.array(df['t'])
        T = t.max()

        # New changepoints from a Poisson process with rate S on [1, T]
        changepoints_t = cast(np.ndarray, self.changepoints_t)
        if T > 1:
            S = len(changepoints_t)
            n_changes = _random(rng).poisson(S * (T - 1))
        else:
            n_changes = 0
        if n_changes > 0:
            changepoint_ts_new = 1 + _random(rng).random(n_changes) * (T - 1)
            changepoint_ts_new.sort()
        else:
            changepoint_ts_new = []

        # Get the empirical scale of the deltas, plus epsilon to avoid NaNs.
        lambda_ = np.mean(np.abs(deltas)) + 1e-8

        # Sample deltas
        deltas_new = _random(rng).laplace(0, lambda_, n_changes)

        # Prepend the times and deltas from the history
        changepoint_ts = np.concatenate((changepoints_t,
                                         changepoint_ts_new))
        deltas = np.concatenate((deltas, deltas_new))

        if self.growth == 'linear':
            trend = self.piecewise_linear(t, deltas, k, m, changepoint_ts)
        elif self.growth == 'logistic':
            cap = df['cap_scaled']
            trend = self.piecewise_logistic(t, cap, deltas, k, m,
                                            changepoint_ts)
        else:
            assert self.growth == "flat"
            trend = self.flat_trend(t, m)

        return trend * cast(float, self.y_scale) + df['floor']

    def sample_predictive_trend_vectorized(
        self,
        df: pd.DataFrame,
        n_samples: int,
        iteration: int = 0,
        rng: np.random.Generator | None = None,
    ) -> np.ndarray[tuple[int, int], np.dtype[np.float64]]:
        """Sample draws of the future trend values. Vectorized version of sample_predictive_trend().

        Parameters
        ----------
        df: Prediction dataframe.
        iteration: Int sampling iteration to use parameters from.
        n_samples: Number of future paths of the trend to simulate.

        Returns
        -------
        Draws of the trend values with shape (n_samples, len(df)). Values are on the scale of the original data.
        """
        deltas = self.params["delta"][iteration]
        m = self.params["m"][iteration]
        k = self.params["k"][iteration]
        changepoints_t = cast(np.ndarray, self.changepoints_t)
        if self.growth == "linear":
            expected = self.piecewise_linear(
                cast(np.ndarray, df["t"].values), deltas, k, m, changepoints_t
            )
        elif self.growth == "logistic":
            expected = self.piecewise_logistic(
                cast(np.ndarray, df["t"].values),
                cast(np.ndarray, df["cap_scaled"].values),
                deltas,
                k,
                m,
                changepoints_t,
            )
        elif self.growth == "flat":
            expected = self.flat_trend(cast(np.ndarray, df["t"].values), m)
        else:
            raise NotImplementedError
        uncertainty = self._sample_uncertainty(df, n_samples, iteration, rng=rng)
        return (
            (np.tile(expected, (n_samples, 1)) + uncertainty) * cast(float, self.y_scale) +
            np.tile(cast(np.ndarray, df["floor"].values), (n_samples, 1))
        )

    def _sample_uncertainty(
        self,
        df: pd.DataFrame,
        n_samples: int,
        iteration: int = 0,
        rng: np.random.Generator | None = None,
    ) -> np.ndarray[tuple[int, int], np.dtype[np.float64]]:
        """Sample draws of future trend changes, vectorizing as much as possible.

        Parameters
        ----------
        df: pd.DataFrame with columns `t` (time scaled to the model context), trend, and cap.
        n_samples: Number of future paths of the trend to simulate
        iteration: The iteration of the parameter set to use. Default 0, the first iteration.

        Returns
        -------
        Draws of the trend changes with shape (n_samples, len(df)). Values are standardized.
        """
        # handle only historic data
        if df["t"].max() <= 1:
            # there is no trend uncertainty in historic trends
            uncertainties = np.zeros((n_samples, len(df)))
        else:
            future_df = df.loc[df["t"] > 1]
            n_length = len(future_df)
            # handle 1 length futures by using history
            if n_length > 1:
                single_diff = np.diff(future_df["t"]).mean()
            else:
                single_diff = np.diff(cast(pd.DataFrame, self.history)["t"]).mean()
            change_likelihood = len(cast(np.ndarray, self.changepoints_t)) * single_diff
            deltas = self.params["delta"][iteration]
            m = self.params["m"][iteration]
            k = self.params["k"][iteration]
            mean_delta = np.mean(np.abs(deltas)) + 1e-8
            if self.growth == "linear":
                mat = self._make_trend_shift_matrix(
                    mean_delta, change_likelihood, n_length, n_samples=n_samples, rng=rng)
                uncertainties = mat.cumsum(axis=1).cumsum(axis=1)  # from slope changes to actual values
                uncertainties *= single_diff  # scaled by the actual meaning of the slope
            elif self.growth == "logistic":
                mat = self._make_trend_shift_matrix(
                    mean_delta, change_likelihood, n_length, n_samples=n_samples, rng=rng)
                uncertainties = self._logistic_uncertainty(
                    mat=mat,
                    deltas=deltas,
                    k=k,
                    m=m,
                    cap=cast(np.ndarray, future_df["cap_scaled"].values),
                    t_time=cast(np.ndarray, future_df["t"].values),
                    n_length=n_length,
                    single_diff=single_diff,
                )
            elif self.growth == "flat":
                # no trend uncertainty when there is no growth
                uncertainties = np.zeros((n_samples, n_length))
            else:
                raise NotImplementedError
            # handle past included in dataframe
            if df["t"].min() <= 1:
                past_uncertainty = np.zeros((n_samples, np.sum(df["t"] <= 1)))
                uncertainties = np.concatenate([past_uncertainty, uncertainties], axis=1)
        return uncertainties

    @staticmethod
    def _make_trend_shift_matrix(
        mean_delta: float, likelihood: float, future_length: int, n_samples: int,
        rng: np.random.Generator | None = None,
    ) -> np.ndarray[tuple[int, int], np.dtype[np.float64]]:
        """
        Creates a matrix of random trend shifts based on historical likelihood and size of shifts.
        Can be used for either linear or logistic trend shifts.
        Each row represents a different sample of a possible future, and each column is a time step into the future.
        """
        # create a bool matrix of where these trend shifts should go
        bool_slope_change = _random(rng).uniform(size=(n_samples, future_length)) < likelihood
        shift_values = _random(rng).laplace(0, mean_delta, size=bool_slope_change.shape)
        mat = shift_values * bool_slope_change
        n_mat = np.hstack([np.zeros((len(mat), 1)), mat])[:, :-1]
        mat = (n_mat + mat) / 2
        return mat

    def _logistic_uncertainty(
        self,
        mat: np.ndarray,
        deltas: np.ndarray,
        k: float,
        m: float,
        cap: np.ndarray,
        t_time: np.ndarray,
        n_length: int,
        single_diff: float | None = None,
    ) -> np.ndarray:
        """
        Vectorizes prophet's logistic uncertainty by creating a matrix of future possible trends.

        Parameters
        ----------
        mat: A trend shift matrix returned by _make_trend_shift_matrix()
        deltas: The size of the trend changes at each changepoint, estimated by the model
        k: Float initial rate.
        m: Float initial offset.
        cap: np.array of capacities at each t.
        t_time: The values of t in the model context (i.e. scaled so that anything > 1 represents the future)
        n_length: For each path, the number of future steps to simulate
        single_diff: The difference between each t step in the model context. Default None, inferred
            from t_time.

        Returns
        -------
        A numpy array with shape (n_samples, n_length), representing the width of the uncertainty interval
        (standardized, not on the same scale as the actual data values) around 0.
        """

        def ffill(arr):
            mask = arr == 0
            idx = np.where(~mask, np.arange(mask.shape[1]), 0)
            np.maximum.accumulate(idx, axis=1, out=idx)
            return arr[np.arange(idx.shape[0])[:, None], idx]

        # for logistic growth we need to evaluate the trend all the way from the start of the train item
        historical_mat, historical_time = self._make_historical_mat_time(
            deltas, cast(np.ndarray, self.changepoints_t), t_time, len(mat), single_diff
        )
        mat = np.concatenate([historical_mat, mat], axis=1)
        full_t_time = np.concatenate([historical_time, t_time])

        # apply logistic growth logic on the slope changes
        k_cum = np.concatenate((np.ones((mat.shape[0], 1)) * k, np.where(mat, np.cumsum(mat, axis=1) + k, 0)), axis=1)
        k_cum_b = ffill(k_cum)
        gammas = np.zeros_like(mat)
        ks = 1 - k_cum_b[:, :-1] / k_cum_b[:, 1:]
        # gamma is 0 wherever no path changes its slope (ks == 0), as is most
        # of the history, so only those steps are computed (same arithmetic)
        for i in np.flatnonzero((ks != 0).any(axis=0)):
            x = full_t_time[i] - m - np.sum(gammas[:, :i], axis=1)
            gammas[:, i] = x * ks[:, i]
        # the data before the -n_length is the historical values, which are not needed, so cut the last n_length
        k_t = (mat.cumsum(axis=1) + k)[:, -n_length:]
        m_t = (gammas.cumsum(axis=1) + m)[:, -n_length:]
        sample_trends = cap / (1 + np.exp(-k_t * (t_time - m_t)))
        # remove the mean because we only need width of the uncertainty centered around 0
        # we will add the width to the main forecast - yhat (which is the mean) - later
        return sample_trends - sample_trends.mean(axis=0)

    def predictive_samples(
        self, df: pd.DataFrame, vectorized: bool = True, rng: np.random.Generator | None = None
    ) -> dict[str, npt.NDArray[np.float64]]:
        """Sample from the posterior predictive distribution. Returns samples
        for the main estimate yhat, and for the trend component. The shape of
        each output will be (nforecast x nsamples), where nforecast is the
        number of points being forecasted (the number of rows in the input
        dataframe) and nsamples is the number of posterior samples drawn.
        This is the argument `uncertainty_samples` in the Prophet constructor,
        which defaults to 1000.

        Parameters
        ----------
        df: Dataframe with dates for predictions (column ds), and capacity
            (column cap) if logistic growth.
        vectorized: Whether to use a vectorized method to compute possible draws. Suggest using
            True (the default) for much faster runtimes in most cases,
            except when (growth = 'logistic' and mcmc_samples > 0).
        rng: Optional numpy Generator for the random draws; None uses NumPy's global RNG.

        Returns
        -------
        Dictionary with keys "trend" and "yhat" containing
        posterior predictive samples for that component.
        """
        regressor_samples = None
        df, regressor_samples = self._prepare_regressors_for_predict(
            df.copy(),
            self.uncertainty_samples if self.uncertainty_samples else None,
            rng=rng,
        )
        df = self.setup_dataframe(df)
        if regressor_samples:
            standardized_samples = {}
            for name, samples in regressor_samples.items():
                props = self.extra_regressors[name]
                standardized_samples[name] = (samples - props['mu']) / props['std']
            regressor_samples = standardized_samples
        return self.sample_posterior_predictive(df, vectorized, regressor_samples, rng=rng)

    def _percentile_skip_constant_rows(self, a: np.ndarray, q: list[float]) -> np.ndarray:
        """Percentiles along axis 1, shape (len(q), len(a)).

        Rows where every sample is equal have that value as every percentile,
        so only the remaining rows are partitioned. Rows with NaNs are never
        treated as constant.
        """
        constant = (a == a[:, :1]).all(axis=1)
        out = np.repeat(a[:, :1].T, len(q), axis=0)
        varying = ~constant
        if varying.any():
            out[:, varying] = self.percentile(a[varying], q, axis=1)
        return out


_CLASSES: dict[type, type] = {}


def seeded(model: Prophet) -> Any:
    """A shallow view of `model` whose predict accepts rng= and history_uncertainty=.

    Parameters
    ----------
    model: A fitted Prophet model (stock or a subclass).

    Returns
    -------
    A shallow copy of the model (sharing its fitted state) of a subclass that adds
    the seeded sampling methods.
    """
    cls = type(model)
    if issubclass(cls, _SeededSampling):
        return model
    if cls not in _CLASSES:
        _CLASSES[cls] = type('Seeded' + cls.__name__, (_SeededSampling, cls), {})
    view = copy.copy(model)
    view.__class__ = _CLASSES[cls]
    return view
